-- Quesshi platform data model. Design draft.
-- PostgreSQL 18. Ids are UUIDv7, generated by the application.
-- Status: reviewed on paper only. It has not been executed against a server yet.
--
-- This one file shows the whole model. When built it is split into migration files that live
-- beside their owner (the core, or a plugin's folder) but run as ONE globally ordered stream,
-- sorted by a timestamp prefix in the file name. Each table below is marked "core" or
-- "plugin: <id>". A plugin's tables may reference core tables, never another plugin's tables, and
-- core tables never reference a plugin's.
--
-- Conventions
--   * Global tables: tenants and their configuration, accounts, admins, sign-in state, jobs.
--   * Every tenant-owned table has tenant_id as the first primary-key column.
--   * Every reference between tenant-owned tables is a composite foreign key that includes
--     tenant_id, so a row can never point into another tenant.
--   * Every tenant-owned table has row-level security (see "access" at the end).
--   * Open sets (kind, format, feature, job kind) are text, validated by the application registry.
--     Closed sets (statuses, roles) are text with a check constraint.
--   * created_at-style defaults are informational. No rule is ever decided from them; every
--     deadline and timing value is written explicitly by the application (see architecture 7.5).

create extension if not exists citext;
create extension if not exists pg_trgm;

-- Which migration files have run. `quesshi migrate` holds one advisory lock for the whole run and
-- refuses to continue if a recorded file's checksum has changed.
create table schema_migrations (
  name       text primary key,                           -- '20261012T1200_core_init.sql'
  owner      text not null,                              -- 'core' or a plugin id
  checksum   text not null,
  applied_at timestamptz not null default now()
);

-- ───────────────────────── roles ─────────────────────────
-- quesshi_owner   owns every object. Used only by `quesshi migrate`. Never used by the server.
-- quesshi_app     request handlers and all tenant work. Bound by row-level security.
--                Cannot read identity tables. Can never see another tenant's rows.
-- quesshi_system  sign-in, tenant lookup, the job worker and timer discovery.
--                Cannot read tenant-owned tables at all, except through the two functions below.
-- No role has BYPASSRLS or SUPERUSER, and none is a member of another.
-- This file runs as quesshi_owner; the two login roles are created by the operator beforehand.

-- The current tenant. Raises when unset, so a query outside a tenant transaction fails loudly.
create function app_tenant() returns uuid
  language sql stable
  return current_setting('app.tenant_id')::uuid;

-- Nothing is executable or readable by default; every grant below is explicit.
alter default privileges revoke execute on functions from public;
alter default privileges revoke all on tables from public;

-- Every tenant-owned table, core or plugin, is registered through this one function, so all of
-- them get the same policy and grants. Run by migrations as quesshi_owner. It refuses a table whose
-- primary key does not start with tenant_id, and records the owner for the catalogue tests.
create function quesshi_tenant_table(t regclass, owner text) returns void
  language plpgsql as $$
begin
  if not exists (
    select 1 from pg_index i
    join pg_attribute a on a.attrelid = i.indrelid and a.attnum = i.indkey[0]
    where i.indrelid = t and i.indisprimary and a.attname = 'tenant_id'
  ) then
    raise exception 'table % must have a primary key starting with tenant_id', t;
  end if;
  execute format('comment on table %s is %L', t, 'owner:' || owner);
  execute format('revoke all on %s from public, quesshi_app, quesshi_system', t);
  execute format('alter table %s enable row level security', t);
  execute format(
    'create policy tenant_isolation on %s for all to quesshi_app
       using (tenant_id = (select app_tenant())) with check (tenant_id = (select app_tenant()))', t);
  execute format('grant select, insert, update, delete on %s to quesshi_app', t);
end $$;

-- ───────────────────────── control plane (core) ─────────────────────────

create table tenants (
  id               uuid primary key,
  slug             text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]*$'),
  name             text not null,
  status           text not null default 'active' check (status in ('active', 'suspended')),
  default_language text not null,
  timezone         text not null default 'UTC',         -- validated by the application on write
  branding         jsonb not null default '{}' check (jsonb_typeof(branding) = 'object'),
  config_version   bigint not null default 0,            -- bumped when capabilities or branding change
  created_at       timestamptz not null default now()
);

-- The languages a tenant offers. tenants.default_language must be one of them; the application
-- checks that whenever either changes.
create table tenant_languages (
  tenant_id    uuid not null references tenants on delete cascade,
  code         text not null,                            -- 'fa', 'en', 'nl'
  name         text not null,                            -- as shown to players, in that language
  english_name text not null,                            -- used in generation prompts
  direction    text not null default 'ltr' check (direction in ('ltr', 'rtl')),
  sort_order   int not null default 0,
  primary key (tenant_id, code)
);

-- Hosts are stored canonical: lower case, no port, no trailing dot, punycode for IDN.
create table tenant_hosts (
  host       text primary key check (host = lower(host) and host !~ '[:/]' and host !~ '\.$'),
  tenant_id  uuid not null references tenants on delete cascade,
  is_primary boolean not null default false              -- used to build absolute links
);
create unique index tenant_hosts_primary on tenant_hosts (tenant_id) where is_primary;
create index tenant_hosts_tenant on tenant_hosts (tenant_id);

-- One row per plugin or core switch per tenant, created by the platform when the tenant is made
-- or a plugin is added. entitled: granted by the platform operator. enabled: chosen by the
-- tenant's admins. A capability is on when both are true.
create table tenant_capabilities (
  tenant_id uuid not null references tenants on delete cascade,
  type      text not null check (type in ('kind', 'format', 'feature', 'signin', 'source', 'switch')),
  key       text not null,
  entitled  boolean not null default true,
  enabled   boolean not null default true,
  settings  jsonb not null default '{}' check (jsonb_typeof(settings) = 'object'),
  primary key (tenant_id, type, key)
);

-- ───────────────────────── identity (core) ─────────────────────────
-- A person has one account across every tenant, and one player profile per tenant they have
-- visited. Everything a tenant owns references the player, never the account.

create table accounts (
  id         uuid primary key,
  email      citext unique,                              -- optional for subject-only external accounts
  created_at timestamptz not null default now(),
  deleted_at timestamptz,
  check (deleted_at is null or email is null)
);

create table account_identities (
  provider   text not null,                              -- 'google'
  subject    text not null,
  account_id uuid not null references accounts on delete cascade,
  primary key (provider, subject)
);
create index account_identities_account on account_identities (account_id);

-- One pending emailed code per address. code_hash is an HMAC keyed by the server secret.
create table login_codes (
  email      citext primary key,
  code_hash  bytea not null,
  attempts   smallint not null default 0 check (attempts >= 0),
  expires_at timestamptz not null,
  created_at timestamptz not null default now()
);

-- A person's profile inside one tenant. A guest is a player with no account.
create table players (
  tenant_id     uuid not null references tenants on delete cascade,
  id            uuid not null,
  account_id    uuid references accounts,                -- accounts are tombstoned, never removed
  display_name  text not null,
  avatar_seed   text not null,
  lang          text not null,
  banned_at     timestamptz,
  deleted_at    timestamptz,                             -- profile scrubbed, row kept for others' history
  created_at    timestamptz not null default now(),
  last_seen_at  timestamptz,                             -- refreshed by an open stream; drives "online"
  primary key (tenant_id, id),
  unique (tenant_id, account_id)                         -- nulls are distinct: many guests per tenant
);
create index players_account on players (account_id) where account_id is not null;

create table admins (
  id                   uuid primary key,
  username             citext not null unique,
  email                citext not null unique,           -- where reset links go
  password_hash        text not null,                    -- ASP.NET Identity's hasher, as today
  is_active            boolean not null default true,    -- a deactivated admin cannot sign in
  last_login_at        timestamptz,
  is_platform          boolean not null default false,   -- may create tenants and set entitlements
  must_change_password boolean not null default false,
  failed_attempts      smallint not null default 0 check (failed_attempts >= 0),
  locked_until         timestamptz,
  created_at           timestamptz not null default now()
);

create table admin_memberships (
  tenant_id uuid not null references tenants on delete cascade,
  admin_id  uuid not null references admins on delete cascade,
  role      text not null default 'owner' check (role in ('owner', 'editor', 'moderator')),
  is_active boolean not null default true,               -- tenant-only admin access; global admin activation stays on admins
  primary key (tenant_id, admin_id)
);
create index admin_memberships_admin on admin_memberships (admin_id);

create table admin_password_resets (
  token_hash bytea primary key,
  admin_id   uuid not null references admins on delete cascade,
  expires_at timestamptz not null,
  used_at    timestamptz
);
create index admin_password_resets_expiry on admin_password_resets (expires_at);

-- One row per signed-in browser on one tenant's host. The cookie holds the token; only its hash is
-- stored. Exactly one of the three subjects is set.
create table auth_sessions (
  token_hash   bytea primary key,
  tenant_id    uuid not null references tenants on delete cascade,
  account_id   uuid references accounts on delete cascade,
  guest_id     uuid,                                     -- a guest player in this tenant
  admin_id     uuid references admins on delete cascade,
  created_at   timestamptz not null default now(),
  last_used_at timestamptz not null default now(),
  expires_at   timestamptz not null,
  revoked_at   timestamptz,
  foreign key (tenant_id, guest_id) references players on delete cascade,
  check (num_nonnulls(account_id, guest_id, admin_id) = 1)
);
create index auth_sessions_account on auth_sessions (account_id) where account_id is not null;
create index auth_sessions_guest on auth_sessions (tenant_id, guest_id) where guest_id is not null;
create index auth_sessions_admin on auth_sessions (admin_id) where admin_id is not null;
create index auth_sessions_expiry on auth_sessions (expires_at);
create index auth_sessions_revoked on auth_sessions (tenant_id, revoked_at) where revoked_at is null;

-- plugin: friends. Friendship is mutual, as today: adding or removing writes or deletes both
-- directions in one transaction, under both players' locks.
create table friendships (
  tenant_id  uuid not null,
  player_id  uuid not null,
  friend_id  uuid not null,
  created_at timestamptz not null default now(),
  primary key (tenant_id, player_id, friend_id),
  foreign key (tenant_id, player_id) references players on delete cascade,
  foreign key (tenant_id, friend_id) references players on delete cascade,
  check (player_id <> friend_id)
);
create index friendships_reverse on friendships (tenant_id, friend_id);

-- ───────────────────────── content (core) ─────────────────────────

-- Immutable once written. A row cannot be deleted while a question or a session snapshot uses it;
-- a clean-up job removes assets nothing references.
create table media_assets (
  tenant_id   uuid not null references tenants on delete cascade,
  id          uuid not null,
  kind        text not null check (kind in ('image', 'audio', 'video')),
  storage_key text not null,                             -- content hash
  mime        text not null,
  bytes       bigint not null check (bytes >= 0),
  meta        jsonb not null default '{}' check (jsonb_typeof(meta) = 'object'),
  attribution text,
  created_at  timestamptz not null default now(),
  primary key (tenant_id, id),
  unique (tenant_id, storage_key)
);

create table categories (
  tenant_id  uuid not null references tenants on delete cascade,
  id         uuid not null,
  slug       text not null,
  names      jsonb not null check (jsonb_typeof(names) = 'object'),   -- {"fa": "...", "en": "..."}
  icon       text not null default '',
  color      text not null default '',
  is_active  boolean not null default true,
  sort_order int not null default 0,
  primary key (tenant_id, id),
  unique (tenant_id, slug)
);

create table questions (
  tenant_id    uuid not null references tenants on delete cascade,
  id           uuid not null,
  kind         text not null,
  kind_version smallint not null default 1 check (kind_version > 0),  -- the kind's payload and behaviour version
  family       text not null,                            -- declared by the kind: 'trivia', 'poll', 'card'
  lang         text not null,
  category_id  uuid,
  level        smallint check (level between 1 and 5),   -- null for kinds with no difficulty
  prompt       text not null,
  payload      jsonb not null check (jsonb_typeof(payload) = 'object'),
  explanation  text,
  topic        text,                                     -- "subject|aspect", for duplicate control
  fingerprint  text,                                     -- normalised prompt words
  status       text not null default 'pending' check (status in ('draft', 'pending', 'approved', 'rejected')),
  source       text not null check (source in ('seed', 'import', 'ai', 'admin', 'player')),
  owner_id     uuid,                                     -- player author; null means the tenant's bank
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  primary key (tenant_id, id),
  foreign key (tenant_id, category_id) references categories on delete set null (category_id),
  foreign key (tenant_id, owner_id) references players on delete cascade,
  check ((source = 'player') = (owner_id is not null))
);
-- The same subject and aspect once per language and family in the bank. Player questions are exempt.
create unique index questions_topic on questions (tenant_id, lang, family, topic)
  where topic is not null and owner_id is null;
-- Drawing items for a session.
create index questions_draw on questions (tenant_id, lang, kind, category_id, level)
  where status = 'approved' and owner_id is null;
create index questions_owner on questions (tenant_id, owner_id) where owner_id is not null;
create index questions_review on questions (tenant_id, status, created_at desc);
create index questions_prompt_trgm on questions using gin (prompt gin_trgm_ops);

-- plugin: stats. Incremented by the plugin's sessionEnded handler, in ascending question id order.
-- Only graded answers count: asked is the number of answers with a credit, misses included as 0.
create table question_stats (
  tenant_id   uuid not null,
  question_id uuid not null,
  served      bigint not null default 0 check (served >= 0),   -- times its slot was opened (today's counter for poll questions)
  asked       bigint not null default 0 check (asked >= 0),    -- graded answers and recorded misses, one per player (today's counter for trivia)
  credit_sum  double precision not null default 0 check (credit_sum >= 0),
  primary key (tenant_id, question_id),
  foreign key (tenant_id, question_id) references questions on delete cascade
);

-- plugin: reports. The question row is locked first, then the report inserted, then counted.
-- Reports are deleted when an admin resolves them, so a corrected question starts from zero.
create table question_reports (
  tenant_id   uuid not null,
  question_id uuid not null,
  player_id   uuid not null,
  reason      text not null,
  note        text,
  created_at  timestamptz not null default now(),
  primary key (tenant_id, question_id, player_id),
  foreign key (tenant_id, question_id) references questions on delete cascade,
  foreign key (tenant_id, player_id) references players on delete cascade
);
create index question_reports_player on question_reports (tenant_id, player_id);

-- An ordered set of questions: a player's custom quiz, a flashcard deck, a curated round.
create table packs (
  tenant_id   uuid not null references tenants on delete cascade,
  id          uuid not null,
  owner_id    uuid,                                      -- null means owned by the tenant
  title       text not null,
  description text,
  lang        text not null,
  visibility  text not null default 'private' check (visibility in ('private', 'unlisted', 'tenant')),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  primary key (tenant_id, id),
  foreign key (tenant_id, owner_id) references players on delete cascade
);
create index packs_owner on packs (tenant_id, owner_id);

create table pack_items (
  tenant_id   uuid not null,
  pack_id     uuid not null,
  question_id uuid not null,
  position    int not null check (position >= 0),
  primary key (tenant_id, pack_id, question_id),
  unique (tenant_id, pack_id, position) deferrable initially deferred,
  foreign key (tenant_id, pack_id) references packs on delete cascade,
  foreign key (tenant_id, question_id) references questions on delete cascade
);
create index pack_items_question on pack_items (tenant_id, question_id);

-- ───────────────────────── sessions (core) ─────────────────────────

create table sessions (
  tenant_id        uuid not null references tenants on delete cascade,
  id               uuid not null,
  code             text not null,                        -- short join code
  format           text not null,
  owner_id         uuid not null,
  lang             text not null,
  status           text not null default 'lobby' check (status in ('lobby', 'running', 'finished', 'cancelled')),
  capacity         int not null check (capacity >= 1),
  content          jsonb not null check (jsonb_typeof(content) = 'object'),   -- ContentSpec
  rules            jsonb not null default '{}' check (jsonb_typeof(rules) = 'object'),
  rules_version    smallint not null default 1 check (rules_version > 0),
  -- Position: what the format is waiting for. A command must name the position it was issued at.
  phase            text not null default 'lobby',
  slot             int not null default -1 check (slot >= -1),   -- shared cursor, for shared-pace formats
  step             int not null default 0 check (step >= 0),     -- turn counter within a slot
  phase_started_at timestamptz,
  revealed_slot    int not null default -1 check (revealed_slot >= -1),   -- shared pacing: answers shown up to here
  due_at           timestamptz,                          -- next moment the engine must act unprompted
  -- A timeout that keeps failing is retried with backoff and finally ends the session as a fault,
  -- so one broken session cannot crowd the others out of the timer loop.
  fault_count      smallint not null default 0 check (fault_count >= 0),
  retry_at         timestamptz,
  -- Bumped on every committed change. Every write by a session's grain is conditional on the
  -- version it last saw, so a second, stale activation of the same grain cannot write.
  version          bigint not null default 0 check (version >= 0),
  -- Working memory while running; the engine empties it on the terminal transition.
  state            jsonb not null default '{}' check (jsonb_typeof(state) = 'object'),
  state_version    smallint not null default 1 check (state_version > 0),
  -- Durable facts the finished view needs beyond places, scores and answers.
  result           jsonb not null default '{}' check (jsonb_typeof(result) = 'object'),
  result_version   smallint not null default 1 check (result_version > 0),
  rematch_of       uuid,
  -- Format endings: completed, forfeit, no_contest. Core endings: owner, admin, expired, fault, outage.
  end_reason       text,
  created_at       timestamptz not null default now(),
  started_at       timestamptz,
  ended_at         timestamptz,
  ended_tz         text,                                 -- the tenant's timezone when it ended; fixes its board periods
  primary key (tenant_id, id),
  unique (tenant_id, rematch_of),
  foreign key (tenant_id, owner_id) references players,
  foreign key (tenant_id, rematch_of) references sessions,
  check (rematch_of is null or rematch_of <> id),
  -- Guards the engine's terminal transition; the engine itself clears state and due_at.
  check (status in ('lobby', 'running') or (state = '{}' and due_at is null)),
  check ((status in ('finished', 'cancelled')) = (ended_at is not null)),
  -- A session that has run has a start time. The one exception is an async duel lobby that
  -- reaches its 48-hour forfeit without ever being started. Every term is true or false, never
  -- null, so the check cannot be passed by accident.
  check (status in ('lobby', 'cancelled')
         or started_at is not null
         or (status = 'finished' and format = 'async_duel'
             and end_reason is not distinct from 'forfeit'))
);
-- A code is reserved only while the session can still be joined or resumed by code.
-- A finished session is addressed by id.
create unique index sessions_code on sessions (tenant_id, code) where status in ('lobby', 'running');
create index sessions_due on sessions (due_at) where due_at is not null;

create table session_participants (
  tenant_id       uuid not null,
  session_id      uuid not null,
  player_id       uuid not null,
  seat            smallint not null check (seat >= 0),
  role            text not null default 'player' check (role in ('player', 'host', 'spectator')),
  status          text not null default 'active' check (status in ('active', 'done', 'left', 'eliminated')),
  -- Personal position, for self-paced formats: commands from this player are checked against it.
  phase           text not null default 'idle',
  slot            int not null default -1 check (slot >= -1),
  step            int not null default 0 check (step >= 0),
  slot_started_at timestamptz,                           -- when that slot's card was served; set only by serve
  revealed_slot   int not null default -1 check (revealed_slot >= -1),   -- personal pacing: answers shown up to here
  -- Fixed when the session starts (or when the seat is taken, if that is later): may this run
  -- count on boards. False for a guest, and it stays false if the guest upgrades part-way through.
  eligible        boolean not null default false,
  score           int not null default 0,                -- may be negative within a session
  place           smallint check (place > 0),
  outcome         text check (outcome in ('win', 'loss', 'draw', 'none')),
  ranked          boolean,                               -- set at the end: eligible, a player seat, a scored format, a normal finish
  state           jsonb not null default '{}' check (jsonb_typeof(state) = 'object'),   -- working memory
  result          jsonb not null default '{}' check (jsonb_typeof(result) = 'object'),  -- durable seat facts
  joined_at       timestamptz not null default now(),
  left_at         timestamptz,
  primary key (tenant_id, session_id, player_id),
  unique (tenant_id, session_id, seat),
  foreign key (tenant_id, session_id) references sessions on delete cascade,
  foreign key (tenant_id, player_id) references players
);
-- A player's history, newest first.
create index participants_history on session_participants (tenant_id, player_id, joined_at desc, session_id);

-- core. Bumped whenever a player's invitations or waiting sessions change. Kept out of `players`
-- so that bumping it never takes a lock on the player row. Bumps are applied last in a
-- transaction, in ascending player id.
create table player_inbox (
  tenant_id uuid not null,
  player_id uuid not null,
  version   bigint not null default 0 check (version >= 0),
  primary key (tenant_id, player_id),
  foreign key (tenant_id, player_id) references players on delete cascade
);

create table session_invites (
  tenant_id  uuid not null,
  session_id uuid not null,
  player_id  uuid not null,
  invited_by uuid not null,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,                       -- set by the format's rule; checked on accept
  primary key (tenant_id, session_id, player_id),
  foreign key (tenant_id, session_id) references sessions on delete cascade,
  foreign key (tenant_id, player_id) references players on delete cascade,
  foreign key (tenant_id, invited_by) references players on delete cascade
);
create index session_invites_player on session_invites (tenant_id, player_id);

-- The question as it was when drawn. Play and history read this, never the questions table.
create table session_items (
  tenant_id    uuid not null,
  session_id   uuid not null,
  slot         int not null check (slot >= 0),
  question_id  uuid,                                     -- source, for statistics; may disappear
  kind         text not null,
  kind_version smallint not null check (kind_version > 0),
  prompt       text not null,
  payload      jsonb not null check (jsonb_typeof(payload) = 'object'),
  -- Written once when the session starts. resolved: whatever the kind fixed for this session
  -- (a shuffle, the frozen roster of options); grading reads it. card and reveal: the two public
  -- sides, stored so history never needs old grading code.
  resolved     jsonb not null default '{}' check (jsonb_typeof(resolved) = 'object'),
  card         jsonb not null check (jsonb_typeof(card) = 'object'),
  reveal       jsonb not null check (jsonb_typeof(reveal) = 'object'),
  media_id     uuid,
  explanation  text,
  level        smallint check (level between 1 and 5),
  category_id  uuid,                                     -- source, for per-category accuracy
  category     jsonb check (jsonb_typeof(category) = 'object'),   -- names, icon, colour as drawn
  primary key (tenant_id, session_id, slot),
  foreign key (tenant_id, session_id) references sessions on delete cascade,
  foreign key (tenant_id, question_id) references questions on delete set null (question_id),
  foreign key (tenant_id, category_id) references categories on delete set null (category_id),
  foreign key (tenant_id, media_id) references media_assets
);
create index session_items_question on session_items (tenant_id, question_id) where question_id is not null;
create index session_items_media on session_items (tenant_id, media_id) where media_id is not null;
create index session_items_category on session_items (tenant_id, category_id) where category_id is not null;

-- One row per answer or recorded miss. seq is assigned by the engine from sessions.step; it is 0
-- except in formats where one player acts more than once in a slot.
create table session_answers (
  tenant_id   uuid not null,
  session_id  uuid not null,
  slot        int not null,
  player_id   uuid not null,
  seq         int not null default 0 check (seq >= 0),
  -- For formats that let a player change an answer until the slot closes (poll). The client sends
  -- a higher revision with each new choice; a retry carries the same one and changes nothing.
  revision    int not null default 0 check (revision >= 0),
  answer      jsonb,                                     -- normalised by the kind; null means a miss
  credit      real check (credit between 0 and 1),       -- null when the kind has no right answer
  points      int not null default 0,                    -- as awarded; never recomputed
  taken_ms    int check (taken_ms >= 0),
  received_at timestamptz not null,                      -- when the server received the command
  primary key (tenant_id, session_id, slot, player_id, seq),
  foreign key (tenant_id, session_id, slot) references session_items on delete cascade,
  foreign key (tenant_id, session_id, player_id) references session_participants on delete cascade
);
-- One player's answers across sessions (accuracy), and the participant foreign key.
create index session_answers_player on session_answers (tenant_id, player_id, session_id);

-- ───────────────────────── stats and leaderboards (plugins) ─────────────────────────

-- plugin: stats. One row per player per finished session it has counted. The aggregates in
-- player_stats are derived from these, so they do not depend on the order events arrive in.
create table player_results (
  tenant_id  uuid not null,
  player_id  uuid not null,
  session_id uuid not null,
  format     text not null,
  ended_at   timestamptz not null,
  outcome    text not null check (outcome in ('win', 'loss', 'draw', 'none')),
  points     int not null default 0,
  primary key (tenant_id, player_id, session_id),
  foreign key (tenant_id, player_id) references players on delete cascade
);
create index player_results_recent on player_results (tenant_id, player_id, format, ended_at desc, session_id);

-- plugin: stats. A player's accuracy per category, as today's profile shows. Counts graded
-- answers and recorded misses; slots a player never reached are not counted.
create table player_category_stats (
  tenant_id   uuid not null,
  player_id   uuid not null,
  category_id uuid not null,
  asked       int not null default 0 check (asked >= 0),
  credit_sum  double precision not null default 0 check (credit_sum >= 0),
  primary key (tenant_id, player_id, category_id),
  foreign key (tenant_id, player_id) references players on delete cascade,
  foreign key (tenant_id, category_id) references categories on delete cascade
);

-- plugin: stats
create table player_stats (
  tenant_id   uuid not null,
  player_id   uuid not null,
  format      text not null,
  played      int not null default 0 check (played >= 0),
  wins        int not null default 0 check (wins >= 0),
  losses      int not null default 0 check (losses >= 0),
  draws       int not null default 0 check (draws >= 0),
  streak      int not null default 0 check (streak >= 0),
  best_streak int not null default 0 check (best_streak >= 0),
  points      bigint not null default 0 check (points >= 0),
  extra       jsonb not null default '{}' check (jsonb_typeof(extra) = 'object'),
  primary key (tenant_id, player_id, format),
  foreign key (tenant_id, player_id) references players on delete cascade
);

-- plugin: leaderboard
-- board: a format id or 'all'. period: 'all', '2026-10' or '2026-W41', derived from the session's
-- end time and ended_tz.
--
-- Today's rule is kept: a penalty takes a score down to zero at most, and an unpaid remainder is
-- forgiven, not carried as debt. That makes the score depend on the order of earnings and
-- penalties, so the plugin keeps a ledger and derives the score from it in time order.

-- One row per abandonment that counts: one per player per session, including a first one that
-- costs nothing. The seven-day tier is counted over these rows, by session end time, across
-- period boundaries. amount is the penalty as currently computed.
create table leaderboard_abandonments (
  tenant_id  uuid not null,
  player_id  uuid not null,
  session_id uuid not null,
  format     text not null,
  ended_at   timestamptz not null,
  ended_tz   text not null,
  amount     int not null default 0 check (amount >= 0),
  primary key (tenant_id, player_id, session_id),
  foreign key (tenant_id, player_id) references players on delete cascade
);
create index leaderboard_abandonments_order on leaderboard_abandonments (tenant_id, player_id, ended_at, session_id);

-- One row per thing that moved a player's score on a board in a period. A session's points and
-- an abandonment's penalty each appear once per board (the format's and 'all') and per period
-- ('all', the month, the week) of the session's end.
create table leaderboard_entries (
  tenant_id  uuid not null,
  board      text not null,
  period     text not null,
  player_id  uuid not null,
  session_id uuid not null,
  kind       text not null check (kind in ('points', 'penalty')),
  at         timestamptz not null,                       -- the session's end
  amount     int not null check (amount >= 0),           -- for a penalty: as currently computed (see architecture 13)
  primary key (tenant_id, board, period, player_id, session_id, kind),
  foreign key (tenant_id, player_id) references players on delete cascade
);
create index leaderboard_entries_order on leaderboard_entries (tenant_id, player_id, board, period, at, session_id);

-- The current score: the ledger folded in (at, session_id) order, and within one session points
-- before its penalty, adding points and subtracting penalties with a floor of zero at each step. last_at and last_session mark how far it is folded,
-- so an entry that arrives in order is applied directly and one that arrives late triggers a refold.
create table leaderboard_scores (
  tenant_id    uuid not null,
  board        text not null,
  period       text not null,
  player_id    uuid not null,
  score        bigint not null default 0 check (score >= 0),
  last_at      timestamptz,
  last_session uuid,
  primary key (tenant_id, board, period, player_id),
  foreign key (tenant_id, player_id) references players on delete cascade
);
create index leaderboard_top on leaderboard_scores (tenant_id, board, period, score desc, player_id);

-- ───────────────────────── operations ─────────────────────────

-- plugin: matchmaking. One waiting entry per player per format.
create table matchmaking_entries (
  tenant_id    uuid not null,
  player_id    uuid not null,
  format       text not null,
  match_key    text not null,                            -- hash of the settings two players must share
  settings     jsonb not null check (jsonb_typeof(settings) = 'object'),   -- those settings, to build the session
  -- Set for formats where the waiting player already has a session others join (async duel).
  session_id   uuid,
  -- A short lease taken by a pairing attempt that must call the session's grain to finish.
  -- claimed_by is that attempt's own token; the entry is removed only by the attempt holding it.
  claimed_by   uuid,
  claimed_until timestamptz,
  enqueued_at  timestamptz not null default now(),
  primary key (tenant_id, player_id, format),
  foreign key (tenant_id, player_id) references players on delete cascade,
  foreign key (tenant_id, session_id) references sessions on delete cascade
);
create index matchmaking_queue on matchmaking_entries (tenant_id, format, match_key, enqueued_at);

-- core. Work that happens outside a request. A worker leases a job, does it, and marks it done.
create table jobs (
  id           bigint generated always as identity primary key,
  tenant_id    uuid references tenants on delete cascade, -- null for platform-wide jobs
  owner        text not null default 'core',             -- 'core' or the plugin id that handles it
  kind         text not null,
  payload      jsonb not null default '{}' check (jsonb_typeof(payload) = 'object'),
  unique_key   text,                                     -- makes enqueueing idempotent
  status       text not null default 'ready' check (status in ('ready', 'done', 'dead', 'cancelled')),
  run_at       timestamptz not null default now(),
  attempts     int not null default 0 check (attempts >= 0),
  max_attempts int default 10 check (max_attempts > 0),   -- null: retried until it succeeds (clean-up)
  locked_by    uuid,                                     -- lease token of the worker holding it
  locked_until timestamptz,
  last_error   text,
  created_at   timestamptz not null default now(),
  finished_at  timestamptz
);
create index jobs_ready on jobs (run_at) where status = 'ready';
create unique index jobs_unique on jobs (tenant_id, owner, kind, unique_key) nulls not distinct
  where unique_key is not null and status = 'ready';

-- plugin: ai_generation (this table and the two after it)
create table generation_runs (
  tenant_id   uuid not null references tenants on delete cascade,
  id          uuid not null,
  status      text not null check (status in ('running', 'finished', 'failed')),
  requested   int not null default 0 check (requested >= 0),
  accepted    int not null default 0 check (accepted >= 0),
  rejected    jsonb not null default '[]' check (jsonb_typeof(rejected) = 'array'),
  started_at  timestamptz not null default now(),
  finished_at timestamptz,
  primary key (tenant_id, id)
);

-- Spend is reserved here before a model call and settled after it.
create table ai_budgets (
  tenant_id    uuid not null references tenants on delete cascade,
  month        text not null,                            -- '2026-10'
  limit_usd    numeric(12, 6) not null check (limit_usd >= 0),
  reserved_usd numeric(12, 6) not null default 0 check (reserved_usd >= 0),
  spent_usd    numeric(12, 6) not null default 0 check (spent_usd >= 0),
  primary key (tenant_id, month)
);

create table ai_calls (
  tenant_id     uuid not null references tenants on delete cascade,
  id            uuid not null,                           -- stable across retries of the same call
  run_id        uuid,
  month         text not null,                           -- the budget month this call was reserved against
  purpose       text not null,
  model         text not null,
  -- reserved: an upper bound of the cost is held. sent: one worker won the right to send and did.
  -- done / failed: settled. expired: never sent, reservation released, never reused.
  -- unknown: sent but no answer was recorded; counted as spent at the reserved bound, never re-sent.
  status        text not null default 'reserved'
                check (status in ('reserved', 'sent', 'done', 'failed', 'expired', 'unknown')),
  reserved_usd  numeric(12, 6) not null default 0 check (reserved_usd >= 0),
  input_tokens  int not null default 0 check (input_tokens >= 0),
  output_tokens int not null default 0 check (output_tokens >= 0),
  cost_usd      numeric(12, 6) not null default 0 check (cost_usd >= 0),
  at            timestamptz not null default now(),
  primary key (tenant_id, id),
  foreign key (tenant_id, run_id) references generation_runs on delete set null (run_id)
);
create index ai_calls_at on ai_calls (tenant_id, at desc);

-- core. The key ring ASP.NET Core uses to protect antiforgery tokens, shared by every silo and
-- kept across restarts.
create table data_protection_keys (
  id            bigint generated always as identity primary key,
  friendly_name text not null unique,
  xml           text not null,
  created_at    timestamptz not null default now()
);

-- core. Global counters for sign-in, which happens before any tenant data is involved.
create table auth_rate_limits (
  key          text not null,                            -- 'code:<email>', 'code-ip:<addr>', 'admin:<username>'
  window_start timestamptz not null,
  count        int not null default 0 check (count >= 0),
  primary key (key, window_start)
);

create table rate_limits (
  tenant_id    uuid not null references tenants on delete cascade,
  key          text not null,                            -- 'report:<player>', 'create:<player>'
  window_start timestamptz not null,
  count        int not null default 0 check (count >= 0),
  primary key (tenant_id, key, window_start)
);

-- core. One row per (plugin, event) whose effects have been applied. An event handler inserts its
-- row and writes its effects in one transaction, so a retried or overlapping job cannot apply twice.
create table plugin_effects (
  tenant_id  uuid not null references tenants on delete cascade,
  plugin     text not null,
  event_key  text not null,                              -- 'sessionEnded:<session id>'
  applied_at timestamptz not null default now(),
  primary key (tenant_id, plugin, event_key)
);
create index plugin_effects_age on plugin_effects (applied_at);

-- core. One counter per ended session, raised whenever the state of any plugin's effects for it
-- changes: a handler finishing, its job dying, a dead job being re-run. A client keeps the report
-- with the highest revision.
create table session_effects (
  tenant_id  uuid not null,
  session_id uuid not null,
  revision   bigint not null default 0 check (revision >= 0),
  primary key (tenant_id, session_id),
  foreign key (tenant_id, session_id) references sessions on delete cascade
);

-- core. actor_id is a global admin id or a player id, by actor_type.
create table audit_log (
  tenant_id   uuid not null references tenants on delete cascade,
  id          bigint generated always as identity,
  actor_type  text not null check (actor_type in ('admin', 'player', 'system')),
  actor_id    uuid,
  action      text not null,
  target_type text,
  target_id   uuid,
  data        jsonb not null default '{}' check (jsonb_typeof(data) = 'object'),
  at          timestamptz not null default now(),
  primary key (tenant_id, id)
);

-- ───────────────────────── access ─────────────────────────
-- Tables are owned by quesshi_owner, which the running server never uses. Row-level security is
-- enabled, not forced: the two run-time roles are not owners, so policies always apply to them.

revoke all on all tables in schema public from public;
revoke all on function quesshi_tenant_table(regclass, text) from public;
revoke all on function app_tenant() from public;
grant execute on function app_tenant() to quesshi_app;

-- 1. Tenant-owned tables: full access for quesshi_app inside its own tenant, nothing for quesshi_system.
--    Core tables are registered here; each plugin's migration registers its own the same way.
select quesshi_tenant_table(t, 'core') from unnest(array[
  'players', 'media_assets', 'categories', 'questions', 'packs', 'pack_items', 'sessions',
  'session_participants', 'session_invites', 'session_items', 'session_answers', 'player_inbox',
  'rate_limits',
  'plugin_effects', 'session_effects', 'audit_log'
]::regclass[]) as t;

-- In the plugins' own migration files:
select quesshi_tenant_table('friendships', 'friends');
select quesshi_tenant_table('question_reports', 'reports');
select quesshi_tenant_table('player_results', 'stats');
select quesshi_tenant_table('player_category_stats', 'stats');
select quesshi_tenant_table('player_stats', 'stats');
select quesshi_tenant_table('question_stats', 'stats');
select quesshi_tenant_table('leaderboard_scores', 'leaderboard');
select quesshi_tenant_table('leaderboard_abandonments', 'leaderboard');
select quesshi_tenant_table('leaderboard_entries', 'leaderboard');
select quesshi_tenant_table('matchmaking_entries', 'matchmaking');
select quesshi_tenant_table('generation_runs', 'ai_generation');
select quesshi_tenant_table('ai_budgets', 'ai_generation');
select quesshi_tenant_table('ai_calls', 'ai_generation');

revoke update, delete on audit_log from quesshi_app;      -- append-only

-- 2. Tenant configuration: quesshi_app reads its own tenant and may change only what a tenant admin
--    may change. Entitlements, hosts, slug and status are platform-only.
alter table tenants enable row level security;
create policy own_tenant on tenants for all to quesshi_app
  using (id = (select app_tenant())) with check (id = (select app_tenant()));
create policy system_all on tenants for all to quesshi_system using (true) with check (true);
grant select on tenants to quesshi_app;
grant update (name, default_language, timezone, branding, config_version) on tenants to quesshi_app;

alter table tenant_languages enable row level security;
create policy own_tenant on tenant_languages for all to quesshi_app
  using (tenant_id = (select app_tenant())) with check (tenant_id = (select app_tenant()));
create policy system_all on tenant_languages for all to quesshi_system using (true) with check (true);
grant select, insert, update, delete on tenant_languages to quesshi_app, quesshi_system;
grant select, insert, update, delete on tenants to quesshi_system;

alter table tenant_hosts enable row level security;
create policy own_tenant on tenant_hosts for select to quesshi_app using (tenant_id = (select app_tenant()));
create policy system_all on tenant_hosts for all to quesshi_system using (true) with check (true);
grant select on tenant_hosts to quesshi_app;
grant select, insert, update, delete on tenant_hosts to quesshi_system;

alter table tenant_capabilities enable row level security;
create policy own_tenant on tenant_capabilities for all to quesshi_app
  using (tenant_id = (select app_tenant())) with check (tenant_id = (select app_tenant()));
create policy system_all on tenant_capabilities for all to quesshi_system using (true) with check (true);
grant select on tenant_capabilities to quesshi_app;
grant update (enabled, settings) on tenant_capabilities to quesshi_app;
grant select, insert, update, delete on tenant_capabilities to quesshi_system;

-- 3. Accounts: a tenant may read (never write) an account that has a player in that tenant.
alter table accounts enable row level security;
create policy members_only on accounts for select to quesshi_app
  using (exists (select 1 from players p
                 where p.account_id = accounts.id and p.tenant_id = (select app_tenant())));
create policy system_all on accounts for all to quesshi_system using (true) with check (true);
grant select on accounts to quesshi_app;
grant select, insert, update on accounts to quesshi_system;

-- 4. Identity and sign-in state: quesshi_system only.
grant select, insert, update, delete on
  account_identities, login_codes, admins, admin_memberships, admin_password_resets,
  auth_sessions, auth_rate_limits, data_protection_keys
  to quesshi_system;

-- 5. Jobs: quesshi_system runs them. quesshi_app cannot read or write the table; it can only add a
--    job for its own tenant through enqueue_job(). A second enqueue with the same unique key while
--    the first is still waiting does nothing.
grant select, insert, update, delete on jobs to quesshi_system;

create function enqueue_job(job_owner text, job_kind text, job_payload jsonb,
                            job_unique_key text default null, job_run_at timestamptz default now())
  returns void
  language sql security definer set search_path = public
  begin atomic
    insert into jobs (tenant_id, owner, kind, payload, unique_key, run_at)
    values (app_tenant(), job_owner, job_kind, job_payload, job_unique_key, job_run_at)
    on conflict do nothing;
  end;
grant execute on function enqueue_job(text, text, jsonb, text, timestamptz) to quesshi_app, quesshi_system;

-- 6. The cross-tenant reads the server needs. They return identifiers (and, for the second, the
--    profile fields a person already owns); all other work on those rows is done by quesshi_app
--    inside the row's tenant.

-- Sessions whose deadline has passed and which are not backing off after a recorded fault.
-- `skip` lets a silo leave out sessions it is already calling or is holding back locally, so
-- stuck ones cannot hide the rest behind the row limit.
create function due_sessions(as_of timestamptz, max_rows int, skip uuid[])
  returns table (tenant_id uuid, id uuid, due_at timestamptz)
  language sql stable security definer set search_path = public
  begin atomic
    select s.tenant_id, s.id, s.due_at from sessions s
    where s.due_at is not null and s.due_at <= as_of
      and (s.retry_at is null or s.retry_at <= as_of)
      and s.id <> all(coalesce(skip, '{}'::uuid[]))
    order by s.due_at, s.id limit greatest(0, least(coalesce(max_rows, 0), 256));
  end;

-- One account's live profiles across tenants: used to pre-fill a first visit and to find what to
-- scrub when the account is deleted. Called only for the account that has just authenticated.
create function account_players(for_account uuid)
  returns table (tenant_id uuid, player_id uuid, display_name text, avatar_seed text, lang text,
                 last_seen_at timestamptz)
  language sql stable security definer set search_path = public
  begin atomic
    select p.tenant_id, p.id, p.display_name, p.avatar_seed, p.lang, p.last_seen_at
    from players p where p.account_id = for_account and p.deleted_at is null;
  end;

-- Called by quesshi_app, inside the tenant transaction that creates a player for an account or
-- attaches an account to a guest. It holds a lock on the account until that transaction ends and
-- raises if the account has been deleted. Deleting an account takes the opposite lock first, so a
-- profile can never be created for an account after its clean-up targets were listed.
create function claim_account(for_account uuid) returns void
  language plpgsql security definer set search_path = public as $$
begin
  perform 1 from accounts a where a.id = for_account and a.deleted_at is null for key share;
  if not found then
    raise exception 'account % is not available', for_account using errcode = 'P0002';
  end if;
end $$;

-- Revokes the current tenant's sessions for a player. The row remains so the request boundary can
-- report a ban without exposing that state to unauthenticated code verification.
create function revoke_player_sessions(for_player uuid) returns void
  language plpgsql security definer set search_path = public as $$
declare
  current_tenant uuid := app_tenant();
  player_account uuid;
begin
  select account_id into player_account
  from players
  where tenant_id = current_tenant and id = for_player and deleted_at is null
  for key share;
  if not found then return; end if;

  update auth_sessions
  set revoked_at = now()
  where tenant_id = current_tenant and revoked_at is null
    and (guest_id = for_player or (player_account is not null and account_id = player_account));
end $$;

revoke all on function due_sessions(timestamptz, int, uuid[]) from public, quesshi_app;
grant execute on function due_sessions(timestamptz, int, uuid[]) to quesshi_system;
grant execute on function account_players(uuid) to quesshi_system;
grant execute on function claim_account(uuid) to quesshi_app;
revoke all on function revoke_player_sessions(uuid) from public, quesshi_system;
grant execute on function revoke_player_sessions(uuid) to quesshi_app;

-- ───────────────────────── Orleans ─────────────────────────
-- Orleans keeps only its cluster membership in PostgreSQL, in its own schema. It holds silo
-- addresses, never tenant data. No grain state and no reminders are stored through Orleans:
-- sessions are written to the tables above by the grain itself, and deadlines use sessions.due_at.
--
-- The provider's published scripts create unqualified objects, so they are run with the search
-- path set, and the membership connection string names the same search path:
--
--   create schema orleans;
--   set search_path = orleans;
--   \i PostgreSQL-Main.sql            -- pinned to the Orleans package version in use
--   \i PostgreSQL-Clustering.sql
--   reset search_path;
--   grant usage on schema orleans to quesshi_system;
--   grant select, insert, update, delete on all tables in schema orleans to quesshi_system;
--   grant execute on all functions in schema orleans to quesshi_system;
--
-- To verify before relying on it: that the scripts shipped with the exact package version install
-- cleanly this way, and that a silo starts with only the quesshi_system credential.
